#!/usr/bin/env bash
#
# Vuelca los cambios de phylax-ui en la plantilla "angular/container" del civi-generator.
#
# - Copia src/ y public/ (y opcionalmente los ficheros raíz) a un directorio temporal.
# - Quita la marca "@autogenerated" que el generador pone en la primera línea.
# - Sustituye las referencias a "phylax" por el placeholder de la plantilla ("Phylax" por el de la etiqueta).
# - Sincroniza el resultado sobre la plantilla con rsync.
#
# Uso:
#   scripts/sync-template.sh [--dry-run] [--delete] [--with-root] [--staged] [ruta...]
#
#   ruta...      Solo vuelca esos ficheros o directorios (dentro de src/ o public/), con su contenido
#                actual. Incompatible con --staged; ignora --delete.
#   --staged     Solo vuelca los ficheros de src/ y public/ que están en el stage de git
#                (con su contenido del índice). Los borrados en stage se borran en la plantilla.
#   --dry-run    Muestra qué cambiaría en la plantilla sin escribir nada.
#   --delete     Borra de la plantilla los ficheros que ya no existen en el proyecto.
#   --with-root  Incluye también los ficheros raíz (angular.json, package.json, Makefile...) y .ci/.
#
# Variables de entorno:
#   TEMPLATE_DIR      Destino (por defecto la plantilla container del civi-generator).
#   NAME_PLACEHOLDER  Placeholder para "phylax" (por defecto "@{base}").
#   LABEL_PLACEHOLDER Placeholder para "Phylax" con mayúscula (por defecto "@{base-label}").
#   HOST_PLACEHOLDER  Placeholder para "net-civeira-phylax" (por defecto "@{api-host}").
#
set -euo pipefail

PROJECT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
TEMPLATE_DIR="${TEMPLATE_DIR:-/Users/ruben.civeiraiglesia/Documents/Proyectos/Personal/civi-generator/repositorios/civi-generator/src/main/resources/template/angular/container}"
NAME="phylax"
DEFAULT_NAME_PLACEHOLDER='@{base}'
DEFAULT_HOST_PLACEHOLDER='@{api-host}'
DEFAULT_LABEL_PLACEHOLDER='@{base-label}'
NAME_PLACEHOLDER="${NAME_PLACEHOLDER:-$DEFAULT_NAME_PLACEHOLDER}"
LABEL_PLACEHOLDER="${LABEL_PLACEHOLDER:-$DEFAULT_LABEL_PLACEHOLDER}"
HOST_PLACEHOLDER="${HOST_PLACEHOLDER:-$DEFAULT_HOST_PLACEHOLDER}"
# El generador solo renombra ficheros con la sintaxis @{...}
FILE_PLACEHOLDER="@{base-name}"

DRY_RUN=""
DELETE=""
WITH_ROOT=0
STAGED=0
PATHS=()
for arg in "$@"; do
  case "$arg" in
    --dry-run) DRY_RUN="--dry-run" ;;
    --delete) DELETE="--delete" ;;
    --with-root) WITH_ROOT=1 ;;
    --staged) STAGED=1 ;;
    -h|--help) sed -n '2,26p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    -*) echo "Opción desconocida: $arg" >&2; exit 1 ;;
    *) PATHS+=("${arg%/}") ;;
  esac
done

if [ "${#PATHS[@]}" -gt 0 ]; then
  [ "$STAGED" -eq 0 ] || { echo "No se pueden combinar rutas con --staged" >&2; exit 1; }
  cd "$PROJECT_DIR"
  for path in "${PATHS[@]}"; do
    case "$path" in
      src/app/features/*|src/app/bootstrap/menu.config.ts|public/i18n/*/*)
        echo "La ruta la genera el modelo, no la plantilla: $path" >&2; exit 1 ;;
      src/*|public/*) ;;
      *) echo "La ruta debe estar dentro de src/ o public/: $path" >&2; exit 1 ;;
    esac
    [ -e "$path" ] || { echo "No existe: $path" >&2; exit 1; }
  done
fi

[ -d "$TEMPLATE_DIR" ] || { echo "No existe la plantilla: $TEMPLATE_DIR" >&2; exit 1; }

# Código específico del proyecto (lo genera el civi-generator a partir del modelo)
EXCLUDES=(
  --exclude='.DS_Store'
  --exclude='/src/app/features/'
  --exclude='/src/app/bootstrap/menu.config.ts'
  --exclude='/public/i18n/*/'
)
ROOT_FILES=(.commitlintrc .gitignore .prettierrc .stylelintrc.json Dockerfile Makefile README.md angular.json package.json
  tsconfig.json tsconfig.app.json tsconfig.spec.json)
ROOT_DIRS=(.ci)

STAGE="$(mktemp -d)"
trap 'rm -rf "$STAGE"' EXIT

echo ">> Copiando a $STAGE"
cd "$PROJECT_DIR"
STAGED_DELETED=()
if [ "$STAGED" -eq 1 ]; then
  # Contenido del índice de git, ignorando lo que genera el modelo
  while IFS=$'\t' read -r status path; do
    case "$path" in
      src/app/features/*|src/app/bootstrap/menu.config.ts|public/i18n/*/*) continue ;;
      src/*|public/*) ;;
      *) continue ;;
    esac
    if [ "$status" = "D" ]; then
      STAGED_DELETED+=("$path")
    else
      mkdir -p "$STAGE/$(dirname "$path")"
      git show ":$path" > "$STAGE/$path"
    fi
  done < <(git diff --cached --name-status --no-renames)
  mkdir -p "$STAGE/src" "$STAGE/public"
  DELETE=""
elif [ "${#PATHS[@]}" -gt 0 ]; then
  # Con una parte del proyecto, --delete borraría de la plantilla todo lo demás
  rsync -a "${EXCLUDES[@]}" --relative "${PATHS[@]}" "$STAGE/"
  mkdir -p "$STAGE/src" "$STAGE/public"
  DELETE=""
else
  rsync -a "${EXCLUDES[@]}" --relative src public "$STAGE/"
fi
if [ "$WITH_ROOT" -eq 1 ]; then
  for f in "${ROOT_FILES[@]}"; do
    [ -f "$f" ] && cp "$f" "$STAGE/"
  done
  for d in "${ROOT_DIRS[@]}"; do
    [ -d "$d" ] && rsync -a --exclude='.DS_Store' "$d" "$STAGE/"
  done
fi

echo ">> Quitando marcas @autogenerated y sustituyendo '$NAME'"
cd "$STAGE"
export NAME NAME_PLACEHOLDER LABEL_PLACEHOLDER HOST_PLACEHOLDER FILE_PLACEHOLDER
# Solo ficheros de texto (grep -I descarta binarios); -r evita que xargs lance perl sin ficheros
grep -rlI --null '' . | xargs -0 -r perl -i -pe '
  BEGIN { $n = quotemeta $ENV{NAME}; $l = quotemeta ucfirst $ENV{NAME}; $h = "net-civeira-" . $n; }
  if ($. == 1) { s{^(?:/\* \@autogenerated \*/|<!-- \@autogenerated -->|# \@autogenerated|// \@autogenerated|\x27 \@autogenerated)\r?\n}{}; }
  s{$h}{$ENV{HOST_PLACEHOLDER}}g;
  # Antes que el reemplazo sin mayúsculas: la etiqueta ("Phylax") tiene su propio placeholder
  s{$l}{$ENV{LABEL_PLACEHOLDER}}g;
  s{$n}{$ENV{NAME_PLACEHOLDER}}gi;
  close ARGV if eof;
'

# Renombra ficheros/directorios que contengan el nombre (de más profundo a menos)
find . -depth -iname "*${NAME}*" | while read -r path; do
  dir="$(dirname "$path")"
  base="$(basename "$path")"
  new="$(printf '%s' "$base" | perl -pe 's/\Q$ENV{NAME}\E/$ENV{FILE_PLACEHOLDER}/gi')"
  mv "$path" "$dir/$new"
done

echo ">> Sincronizando con $TEMPLATE_DIR ${DRY_RUN:+(dry-run)}"
rsync -rlc --itemize-changes $DRY_RUN $DELETE "${EXCLUDES[@]}" "$STAGE/src" "$STAGE/public" "$TEMPLATE_DIR/" | grep -v '^\.' || true
for path in ${STAGED_DELETED[@]+"${STAGED_DELETED[@]}"}; do
  target="$TEMPLATE_DIR/$(printf '%s' "$path" | perl -pe 's/\Q$ENV{NAME}\E/$ENV{FILE_PLACEHOLDER}/gi')"
  if [ -e "$target" ]; then
    echo "*deleting $path"
    [ -n "$DRY_RUN" ] || rm -f "$target"
  fi
done
if [ "$WITH_ROOT" -eq 1 ]; then
  for f in "${ROOT_FILES[@]}"; do
    [ -f "$STAGE/$f" ] && rsync -c --itemize-changes $DRY_RUN "$STAGE/$f" "$TEMPLATE_DIR/$f" | grep -v '^\.' || true
  done
  for d in "${ROOT_DIRS[@]}"; do
    # -p conserva el bit de ejecución de los scripts
    [ -d "$STAGE/$d" ] && rsync -rlcp --itemize-changes $DRY_RUN $DELETE "$STAGE/$d" "$TEMPLATE_DIR/" | grep -v '^\.' || true
  done
fi

echo ">> Hecho"
